import {requireCondition,deepFreeze} from '../contracts.js'
import {campaignDefinitions,CAMPAIGN_DECISIONS} from './definitions.js'
export function createCampaignFoundation({runtime,catalogue,enabled=true,definitions=campaignDefinitions(catalogue),hasContent=()=>false}){
 const listeners=new Set(),registeredContent=new Map();let closed=false,syncing=false,error=null,view,conversation=null
 function project(){const {progress,session}=runtime.snapshot(),journal=progress.campaignJournal??{attempts:{},decisions:{},characters:{}};const missions=definitions.map(d=>{const content=registeredContent.get(d.id),complete=progress.completedMissionIds.includes(d.id),prerequisites=d.prerequisites.filter(id=>!progress.completedMissionIds.includes(id)),choices=d.decisionRequirements.filter(r=>journal.decisions[r.id]!==r.choice),live=session?.missionId===d.id?session:null,failed=live?(live.state==='failed'||live.playerResources?.health===0||live.failedObjectiveIds?.length>0):journal.attempts[d.id]?.state==='failed',state=live&&failed?'failed':live&&!['failed','completed','releasing'].includes(live.state)?'active':complete?'completed':prerequisites.length||choices.length?'locked':failed?'failed':'unlocked';return {...d,description:content?.description??d.description,worlds:content?.worldId?[content.worldId]:d.worlds,mainObjective:content?.mainObjective??d.mainObjective,storyBriefings:content?.story?.briefings??{},subObjectives:content?content.objectives.map(o=>({id:o.id,label:o.label??o.id,optional:o.required===false,source:o.source,prerequisites:o.prerequisites??[]})):d.subObjectives,rewards:content?.rewards??d.rewards,state,completed:complete,registered:hasContent(d.id),reason:!complete&&prerequisites.length?'Complete '+prerequisites.join(', '):choices.length?'Requires recorded campaign decision':!hasContent(d.id)?'Runtime content not implemented':null,canStart:(complete||(!prerequisites.length&&!choices.length))&&hasContent(d.id),canRecover:Boolean(progress.missionCheckpoints?.[d.id]&&hasContent(d.id)),interrupted:!live&&journal.attempts[d.id]?.state==='active',checkpoint:progress.missionCheckpoints?.[d.id]?.checkpointId??null,objectiveStates:live?.objectiveStates??{},completedSubObjectives:live?.completedObjectiveIds??[]}});view=deepFreeze({enabled,error,conversation:conversation?structuredClone(conversation):null,missions,characters:{...journal.characters},decisions:{...journal.decisions},completed:missions.filter(m=>m.state==='completed').length});for(const fn of [...listeners])try{fn()}catch{/* Presentation does not invalidate campaign transactions. */}}
 function sync(){if(closed||syncing)return;syncing=true;try{if(enabled){const s=runtime.snapshot().session;if(s&&['active','failed'].includes(s.state)){const state=s.state==='failed'||s.playerResources?.health===0||s.failedObjectiveIds?.length?'failed':'active',old=runtime.snapshot().progress.campaignJournal?.attempts[s.missionId];if(old?.state!==state||old?.attemptId!==s.id)runtime.recordCampaign({type:'attempt',id:s.missionId,state,attemptId:s.id})}}error=null}catch(e){error=e.message}finally{syncing=false;project()}}
 const stop=runtime.subscribe(sync);sync()
 return {registerContent(content){requireCondition(catalogue.canSelect(content?.missionId)&&hasContent(content.missionId)&&Array.isArray(content.objectives),'MISSING_RUNTIME_CONTENT','Registered authored content required');registeredContent.set(content.missionId,structuredClone({objectives:content.objectives,rewards:content.rewards??[],worldId:content.worldId,description:content.description,mainObjective:content.mainObjective,story:content.story}));project()},setConversation(value){conversation=value?structuredClone(value):null;project()},snapshot:()=>view,subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn)},assertCanStart(id){const mission=view.missions.find(m=>m.id===id);requireCondition(mission,'UNKNOWN_MISSION','Unknown campaign mission');requireCondition(mission.state!=='locked','MISSION_LOCKED',mission.reason);requireCondition(mission.registered,'MISSING_RUNTIME_CONTENT','Mission runtime is not implemented');return mission},choose(id,choice){const d=CAMPAIGN_DECISIONS[id];requireCondition(d?.choices.includes(choice),'INVALID_STORY_DECISION','Decision/choice has no project definition');runtime.recordCampaign({type:'decision',id,choice})},recordCharacter(id,patch){runtime.recordCampaign({type:'character',id,patch})},retry:sync,release(){if(closed)return;closed=true;stop();listeners.clear()}}
}
